17	import {
18	  ANNOTATION_LOCATION,
19	  ANNOTATION_ORIGIN_LOCATION,
20	} from '@backstage/catalog-model';
21	import {
22	  EntityProvider,
23	  EntityProviderConnection,
24	} from '@backstage/plugin-catalog-node';
25	import {
