27	  CatalogScmEventsService,
28	} from '@backstage/plugin-catalog-node/alpha';
29	import { Knex } from 'knex';
30	import { chunk } from 'lodash';
31	import {
32	  DbRefreshKeysRow,
33	  DbRefreshStateRow,
34	  DbSearchRow,
35	} from '../database/tables';
36	import { ScmEventHandlingConfig } from '../util/readScmEventHandlingConfig';
