38	/**
39	 * Deals in a generic fashion with SCM events, refreshing entities as needed.
40	 *
41	 * It's implemented in the form of an entity provider even though its actually
42	 * does not behave like one, mostly in order to consistently start treating
43	 * events on connect time when the engine is known to be ready.
44	 */
45	export class GenericScmEventRefreshProvider implements EntityProvider {
46	  readonly #knex: Knex;
47	  readonly #scmEvents: CatalogScmEventsService;
48	  readonly #scmEventHandlingConfig: ScmEventHandlingConfig;
49	
50	  constructor(
51	    knex: Knex,
52	    scmEvents: CatalogScmEventsService,
53	    scmEventHandlingConfig: ScmEventHandlingConfig,
54	  ) {
55	    this.#knex = knex;
56	    this.#scmEvents = scmEvents;
57	    this.#scmEventHandlingConfig = scmEventHandlingConfig;
58	  }
59	
60	  getProviderName(): string {
61	    return 'GenericScmEventRefreshProvider';
62	  }
63	
64	  async connect(_connection: EntityProviderConnection): Promise<void> {
65	    if (this.#scmEventHandlingConfig.refresh) {
66	      this.#scmEvents.subscribe({ onEvents: this.#onScmEvents.bind(this) });
67	    }
68	  }
69	
70	  async #onScmEvents(events: CatalogScmEvent[]): Promise<void> {
71	    const exactLocationsToRefresh = new Set<string>();
72	    const locationPrefixesToRefresh = new Set<string>();
73	
74	    for (const event of events) {
75	      if (event.type === 'location.updated') {
76	        exactLocationsToRefresh.add(event.url);
77	      } else if (event.type === 'repository.updated') {
78	        if (!event.url.match(/[?#]/)) {
79	          // TODO(freben): We can't yet support complex URL locations where e.g.
80	          // the path can be anywhere in the URL including in the query or hash
81	          // part. The code below currently assumes that we can use simple
82	          // substring operations.
83	          locationPrefixesToRefresh.add(event.url.replace(/\/*$/g, '/'));
84	        }
85	      }
86	    }
87	
88	    let count = 0;
89	
90	    // Perform exact location updates
91	    for (const urls of chunk(
92	      expandUrlVariations(exactLocationsToRefresh),
93	      50,
94	    )) {
95	      const result = await this.#knex<DbRefreshStateRow>('refresh_state')
96	        .update({ next_update_at: this.#knex.fn.now() })
97	        .whereIn('entity_id', keysQuery => {
98	          return keysQuery
99	            .table<DbRefreshKeysRow>('refresh_keys')
100	            .select('entity_id')
101	            .whereIn('key', urls)
102	            .union(searchQuery => {
103	              return searchQuery
104	                .table<DbSearchRow>('search')
105	                .select('entity_id')
106	                .whereIn('key', [
107	                  `metadata.annotations.${ANNOTATION_LOCATION}`,
108	                  `metadata.annotations.${ANNOTATION_ORIGIN_LOCATION}`,
109	                ])
110	                .whereIn('value', urls);
111	            });
112	        });
113	
114	      count += Number(result);
115	    }
116	
117	    // Perform prefix updates
118	    for (const prefixes of chunk(
119	      expandUrlVariations(locationPrefixesToRefresh),
120	      10,
121	    )) {
122	      const result = await this.#knex<DbRefreshStateRow>('refresh_state')
123	        .update({ next_update_at: this.#knex.fn.now() })
124	        .whereIn('entity_id', keysQuery => {
125	          return keysQuery
126	            .table<DbRefreshKeysRow>('refresh_keys')
127	            .select('entity_id')
128	            .where(inner =>
129	              prefixes.reduce(
130	                (acc, prefix) => acc.orWhere('key', 'like', `${prefix}%`),
131	                inner,
132	              ),
133	            )
134	            .union(searchQuery => {
135	              return searchQuery
136	                .table<DbSearchRow>('search')
137	                .select('entity_id')
138	                .whereIn('key', [
139	                  `metadata.annotations.${ANNOTATION_LOCATION}`,
140	                  `metadata.annotations.${ANNOTATION_ORIGIN_LOCATION}`,
141	                ])
142	                .where(inner =>
143	                  prefixes.reduce(
144	                    (acc, prefix) => acc.orWhere('value', 'like', `${prefix}%`),
145	                    inner,
146	                  ),
147	                );
148	            });
149	        });
150	
151	      count += Number(result);
152	    }
153	  }
154	}
155	
156	/**
157	 * Given a URL, returns all variations of that URL that may come into play for
158	 * refreshes.
159	 *
160	 * This covers the oddity that the catalog sometimes uses `/tree/` instead of
161	 * `/blob/` GitHub URLs, and in some circumstances there's a `url:` prefix and
162	 * sometimes not.
163	 */
164	function expandUrlVariations(urls: Iterable<string>): string[] {
165	  const variations = new Set<string>();
166	  for (const url of urls) {
167	    variations.add(`url:${url}`);
168	    variations.add(`url:${url.replace('/blob/', '/tree/')}`);
169	  }
170	  return Array.from(variations);
